import math


def calculate(left: float, operator: str, right: float) -> float:
    """Calculate one operation, rejecting invalid operators and zero divisors."
    Supports +, -, *, /, and ** (exponentiation). Results must be finite real numbers."""
    if operator == "+":
        return left + right
    if operator == "-":
        return left - right
    if operator == "*":
        return left * right
    if operator == "/":
        if right == 0:
            raise ValueError("Cannot divide by zero.")
        return left / right
    if operator == "**":
        # Check for cases where exponentiation is not defined or not finite
        try:
            result = math.pow(left, right)
        except (ValueError, OverflowError):
            raise ValueError("Result is not a finite real number.")
        if not math.isfinite(result):
            raise ValueError("Result is not a finite real number.")
        # math.pow returns float('nan') for negative base with fractional exponent
        if math.isnan(result):
            raise ValueError("Result is not a finite real number.")
        return result
    raise ValueError("Choose +, -, *, /, or **.")


def read_number(prompt: str) -> float:
    """Read a finite number, allowing the user to retry invalid input."""
    while True:
        try:
            number = float(input(prompt))
            if math.isfinite(number):
                return number
        except ValueError:
            pass
        print("Please enter a finite number.")


def main() -> None:
    print("Calculator: +, -, *, /, ** (enter q to quit)")
    try:
        while True:
            operator = input("Operation: ").strip().lower()
            if operator in {"q", "quit", "exit"}:
                break
            if operator not in {"+", "-", "*", "/", "**"}:
                print("Choose +, -, *, /, or **.")
                continue
            left = read_number("First number: ")
            right = read_number("Second number: ")
            try:
                result = calculate(left, operator, right)
                print(f"Result: {result:g}")
            except ValueError as error:
                print(error)
    except (EOFError, KeyboardInterrupt):
        print()
    print("Goodbye!")


if __name__ == "__main__":
    main()

